import unittest
from candidate import common

class TestCommonElements(unittest.TestCase):
    def test_common_elements_normal_case(self):
        self.assertEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121]), [1, 5, 653])

    def test_common_elements_empty_lists(self):
        self.assertEqual(common([], []), [])

    def test_common_elements_single_element(self):
        self.assertEqual(common([1], [1]), [1])

    def test_common_elements_no_common_elements(self):
        self.assertEqual(common([1, 2, 3], [4, 5, 6]), [])

    def test_common_elements_duplicates_in_lists(self):
        self.assertEqual(common([1, 1, 2, 2], [1, 2, 3]), [1, 2])

    def test_common_elements_duplicates_in_result(self):
        self.assertEqual(common([1, 2, 2, 3], [2, 2, 4]), [2])

    def test_common_elements_with_negative_numbers(self):
        self.assertEqual(common([-1, -2, 3], [-2, 0, -2]), [-2])

    def test_common_elements_with_floats(self):
        self.assertEqual(common([1.5, 2.5, 3.5], [2.5, 4.5, 1.5]), [1.5, 2.5])

    def test_common_elements_with_mixed_types(self):
        with self.assertRaises(TypeError):
            common([1, 2, 'a'], [1, 'b', 3])

    def test_common_elements_none_input(self):
        with self.assertRaises(TypeError):
            common(None, [1, 2, 3])

    def test_common_elements_empty_first_list(self):
        self.assertEqual(common([], [1, 2, 3]), [])

    def test_common_elements_empty_second_list(self):
        self.assertEqual(common([1, 2, 3], []), [])

    def test_common_elements_large_numbers(self):
        self.assertEqual(common([1000000, 2000000], [2000000, 3000000]), [2000000])

    def test_common_elements_unicode_characters(self):
        self.assertEqual(common(['a', 'b', 'c'], ['b', 'd', 'c']), ['b', 'c'])
